    ('7f3ee5a8-2e8b-5b5f-89f9-2a61ab0a6809'::uuid, 'maths', '3e', 'Fonction linéaire et proportionnalité', 7, 'Organisation et gestion de données – Fonctions'),
    ('473ec628-85ca-5745-a85e-de1b974853e3'::uuid, 'maths', '3e', 'Les fonctions affines', 8, 'Organisation et gestion de données – Fonctions'),
